import ProductReveal from "./ProductReveal";

/* Illustrations are generated by scripts/abstract-competitive-history.py from public-domain references.
   They are about strategy and teamwork; who the figures are is left for the image to say.
   They do not sit together: each one is placed along the Competitive path beside the step it speaks to,
   alternating sides, so the path reads plan -> call -> team -> record. */

/* Scenes: no frames; each dissolves into the page, lit around its leader. */
const scenes = {
  strategy: {
    line: "One plan. Every rank behind it.",
    image: "/assets/realms/competitive-history-strategy.svg",
    alt: "A commander in a crested helmet, lit in amber, raises his fist before a line of armoured officers on the eve of battle, drawn from a 19th-century illustration.",
  },
  teamwork: {
    line: "Many minds. One problem.",
    image: "/assets/realms/competitive-history-teamwork.svg",
    alt: "A slim man in a pale hat, lit in amber, leans over the twisted base of a steel tower in the desert while the people around him look on, abstracted from a 1945 photograph.",
  },
} as const;

/* Symbols use the same abstraction, but are shown as cut-outs:
   only the figures the reference's frame does not cut through, on a transparent ground, with no frame or mask. */
const symbols = {
  leadership: {
    line: "Make the call your team can follow.",
    image: "/assets/realms/competitive-symbol-leadership.svg",
    width: 1200,
    height: 890,
    alt: "A commander in a windblown robe, lit in amber, pours the water from his helmet onto the ground while his soldiers and the marching column look on, abstracted from a painting.",
  },
  accountability: {
    line: "Every move, on the record.",
    image: "/assets/realms/competitive-symbol-accountability.svg",
    width: 1024,
    height: 683,
    alt: "A man lit in amber sits at a witness table before a microphone, facing two questioners, with a full gallery watching behind him, abstracted from a film still.",
  },
} as const;

function LegendScene({ scene }: { scene: keyof typeof scenes }) {
  const s = scenes[scene];
  return <ProductReveal className="competitive-legend-reveal">
    <figure className="competitive-legend" data-legend={scene}>
      <div className="competitive-legend-art">
        <img src={s.image} width="960" height="640" alt={s.alt} loading="lazy" decoding="async" />
      </div>
      <figcaption>
        <h3>{s.line}</h3>
      </figcaption>
    </figure>
  </ProductReveal>;
}

/** Opens the history thread right after the match board: the section heading and the strategy scene. */
export function CompetitiveLegendsIntro() {
  return <section className="competitive-legends competitive-interlude" data-interlude="strategy" aria-labelledby="competitive-legends-heading">
    <div className="product-container">
      <header className="competitive-legends-heading">
        <div>
          <p className="product-eyebrow">Strategy / Teamwork / Competition</p>
          <h2 id="competitive-legends-heading">Every great plan<br /><span>needed a team.</span></h2>
        </div>
        <p>Read the field. Take a role. Move before the other side does.</p>
      </header>
      <LegendScene scene="strategy" />
    </div>
  </section>;
}

/** A single scene between two sections of the path. */
export function CompetitiveLegendInterlude({ scene }: { scene: keyof typeof scenes }) {
  return <div className="competitive-interlude" data-interlude={scene}>
    <div className="product-container"><LegendScene scene={scene} /></div>
  </div>;
}

/** A single cut-out symbol between two sections of the path. */
export function CompetitiveSymbolInterlude({ symbol }: { symbol: keyof typeof symbols }) {
  const s = symbols[symbol];
  return <div className="competitive-interlude" data-interlude={symbol}>
    <div className="product-container">
      <ProductReveal className="competitive-symbol-reveal">
        <figure className="competitive-symbol" data-symbol={symbol}>
          <img src={s.image} width={s.width} height={s.height} alt={s.alt} loading="lazy" decoding="async" />
          <figcaption>
            <h3>{s.line}</h3>
          </figcaption>
        </figure>
      </ProductReveal>
    </div>
  </div>;
}
